{{(() => {
  const who = MerchantSelect.selectedOptionValue && MerchantSelect.selectedOptionValue !== 'all' ? (MerchantSelect.selectedOptionLabel || '') : null;
  const e = (n) => (Number(n) || 0).toFixed(2) + ' €';
  const last = appsmith.store.last_payout_id ? `\nПоследно изплащане: ${appsmith.store.last_payout_id}` : '';
  if (!who) return 'Изплащане: избери клиент, за да видиш какво му дължим.';
  const p = GetPendingPayout.data;
  if (!p || !p.totals) return `Изплащане на ${who}: изчислява се…`;
  const t = p.totals;
  const r = (p.returns && p.returns.totals) || {};
  const withheld = Number(r.withheld) || 0;
  const carried = Number(r.carried) || 0;
  if (!t.orders) {
    // Nothing to pay, but a debt can still be sitting there: say so rather than
    // letting "no unpaid orders" read as "nothing outstanding either way".
    const owes = withheld + carried;
    return owes
      ? `Няма неизплатени поръчки за ${who}.\nДължи ни ${e(owes)} за върнати пратки — удържа се от следващото изплащане.${last}`
      : `Няма неизплатени поръчки за ${who}.${last}`;
  }
  // ПРЕВЕДИ what the system will record, never t.owed: the payout withholds return
  // charges and stamps them, so paying out t.owed by hand overpays the merchant and
  // leaves the stamp disagreeing with the bank. See ReturnChargeService.
  const head = withheld
    ? `Преведи на ${who}: ${e(t.net)}\nНаложен платеж ${e(t.owed)} по ${t.orders} ${t.orders === 1 ? 'поръчка' : 'поръчки'} − ${e(withheld)} за ${r.count} ${r.count === 1 ? 'върната пратка' : 'върнати пратки'}`
    : `Дължим на ${who}: ${e(t.owed)} по ${t.orders} ${t.orders === 1 ? 'поръчка' : 'поръчки'}`;
  const rest = carried ? `\nОще ${e(carried)} за върнати остават за следващо изплащане (не се събират в това).` : '';
  return `${head}
Събрано ${e(t.collected)} (в брой ${e(t.cash)}, с карта ${e(t.card)}) − наши ${e(t.revenue)}${rest}${last}`;
})()}}
